corrected_code:
import fastifyHttpProxy from '@fastify/http-proxy';

fastify.register(fastifyHttpProxy, {
  upstream: process.env.K8S_MANAGEMENT_SERVICE,
  prefix: '/k8s/clusters/:clusterId',
  preHandler: [
    fastify.authenticate,
    async (request, reply) => {
      const { clusterId } = request.params;
      const grant = await prisma.clusterAccessGrant.findFirst({
        where: { clusterId, userId: request.user.id }
      });
      if (!grant) {
        return reply.status(403).send({ error: 'Forbidden: no access grant for this Kubernetes cluster' });
      }
    }
  ],
  rewritePrefix: '/api/v1/k8s'
});
